import React, { useState, useEffect } from 'react';
import { Task } from '../types';

const OrganizeView: React.FC = () => {
  // Pomodoro State
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [isBreak, setIsBreak] = useState(false);

  // Tasks State
  const [tasks, setTasks] = useState<Task[]>([]);
  const [newTaskText, setNewTaskText] = useState('');

  useEffect(() => {
    let interval: any = null;
    if (isActive && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft(timeLeft - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      clearInterval(interval);
      setIsActive(false);
      const nextSession = !isBreak;
      setIsBreak(nextSession);
      setTimeLeft(nextSession ? 5 * 60 : 25 * 60);
      alert(nextSession ? "C'est l'heure de la pause !" : "C'est l'heure de se concentrer !");
    }
    return () => clearInterval(interval);
  }, [isActive, timeLeft, isBreak]);

  const toggleTimer = () => setIsActive(!isActive);
  const resetTimer = () => {
    setIsActive(false);
    setIsBreak(false);
    setTimeLeft(25 * 60);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const addTask = (priority: 'high' | 'medium' | 'low') => {
    if (!newTaskText.trim()) return;
    const newTask: Task = {
      id: Date.now().toString(),
      text: newTaskText,
      priority,
      completed: false,
    };
    setTasks([...tasks, newTask]);
    setNewTaskText('');
  };

  const toggleTask = (id: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <h2 className="text-3xl font-bold text-gray-800">Organisation Efficace</h2>

      {/* Pomodoro Section */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 flex flex-col items-center text-center">
        <h3 className="text-xl font-semibold mb-2">Méthode Pomodoro</h3>
        <p className="text-gray-500 text-sm mb-6 italic">25 min de travail concentré, 5 min de pause.</p>

        <div className={`text-7xl font-mono font-bold mb-8 ${isBreak ? 'text-emerald-500' : 'text-indigo-600'}`}>
          {formatTime(timeLeft)}
        </div>

        <div className="flex space-x-4">
          <button 
            onClick={toggleTimer}
            className={`px-8 py-3 rounded-full font-bold text-white transition-all ${
              isActive ? 'bg-orange-500 hover:bg-orange-600' : 'bg-indigo-600 hover:bg-indigo-700'
            }`}
          >
            {isActive ? 'Pause' : 'Démarrer'}
          </button>
          <button 
            onClick={resetTimer}
            className="px-8 py-3 rounded-full font-bold bg-gray-100 text-gray-600 hover:bg-gray-200"
          >
            Réinitialiser
          </button>
        </div>
      </section>

      {/* Eisenhower Matrix / Task Prioritization */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h3 className="text-xl font-semibold mb-4">Matrice de Priorité</h3>
        <div className="flex space-x-2 mb-6">
          <input 
            type="text" 
            value={newTaskText}
            onChange={(e) => setNewTaskText(e.target.value)}
            placeholder="Nouvelle tâche..."
            className="flex-grow p-3 border rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none"
          />
          <button onClick={() => addTask('high')} className="bg-red-100 text-red-700 px-3 py-1 rounded-lg text-xs font-bold hover:bg-red-200">Urgent</button>
          <button onClick={() => addTask('medium')} className="bg-blue-100 text-blue-700 px-3 py-1 rounded-lg text-xs font-bold hover:bg-blue-200">Important</button>
          <button onClick={() => addTask('low')} className="bg-gray-100 text-gray-700 px-3 py-1 rounded-lg text-xs font-bold hover:bg-gray-200">À faire</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {(['high', 'medium', 'low'] as const).map(prio => (
            <div key={prio} className="space-y-3">
              <h4 className={`text-xs font-bold uppercase tracking-widest ${
                prio === 'high' ? 'text-red-500' : prio === 'medium' ? 'text-blue-500' : 'text-gray-500'
              }`}>
                {prio === 'high' ? 'Urgent & Important' : prio === 'medium' ? 'Important' : 'Secondaire'}
              </h4>
              <div className="bg-gray-50 p-3 rounded-xl min-h-[100px] space-y-2">
                {tasks.filter(t => t.priority === prio).map(task => (
                  <div 
                    key={task.id}
                    onClick={() => toggleTask(task.id)}
                    className={`p-2 rounded bg-white border cursor-pointer text-sm flex items-center transition-opacity ${
                      task.completed ? 'opacity-50 line-through' : ''
                    }`}
                  >
                    <div className={`w-2 h-2 rounded-full mr-2 ${
                      prio === 'high' ? 'bg-red-400' : prio === 'medium' ? 'bg-blue-400' : 'bg-gray-400'
                    }`} />
                    {task.text}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default OrganizeView;

import React, { useState, useEffect } from 'react';

const RelaxView: React.FC = () => {
  const [breathePhase, setBreathePhase] = useState<'inspire' | 'maintien' | 'expire'>('inspire');
  const [counter, setCounter] = useState(4);

  useEffect(() => {
    const timer = setInterval(() => {
      setCounter((prev) => {
        if (prev <= 1) {
          if (breathePhase === 'inspire') {
            setBreathePhase('maintien');
            return 4;
          } else if (breathePhase === 'maintien') {
            setBreathePhase('expire');
            return 4;
          } else {
            setBreathePhase('inspire');
            return 4;
          }
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [breathePhase]);

  const getPhaseText = () => {
    switch (breathePhase) {
      case 'inspire': return 'Inspirez lentement...';
      case 'maintien': return 'Maintenez...';
      case 'expire': return 'Expirez doucement...';
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <h2 className="text-3xl font-bold text-gray-800">Gestion du Stress</h2>

      <section className="bg-white p-12 rounded-2xl shadow-sm border border-gray-100 flex flex-col items-center overflow-hidden">
        <h3 className="text-xl font-semibold mb-8">Respiration Carrée</h3>

        <div className="relative flex items-center justify-center w-64 h-64">
          <div className={`absolute w-32 h-32 bg-indigo-500 rounded-full blur-xl transition-all duration-1000 ${
            breathePhase === 'inspire' ? 'scale-[2] opacity-60' : breathePhase === 'maintien' ? 'scale-[2] opacity-80' : 'scale-100 opacity-30'
          }`} />
          <div className={`z-10 w-32 h-32 border-4 border-indigo-600 rounded-full flex items-center justify-center text-3xl font-bold text-indigo-700 bg-white transition-all duration-1000 ${
            breathePhase === 'inspire' ? 'scale-[1.8]' : breathePhase === 'maintien' ? 'scale-[1.8]' : 'scale-100'
          }`}>
            {counter}
          </div>
        </div>

        <p className="mt-12 text-2xl font-medium text-indigo-900 h-8">
          {getPhaseText()}
        </p>
      </section>

      <section className="grid md:grid-cols-2 gap-6">
        <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100">
          <h4 className="font-bold text-emerald-800 mb-2">💡 La Pause Active</h4>
          <p className="text-sm text-emerald-700 leading-relaxed">
            Toutes les heures, lève-toi 5 minutes. Étire tes bras, marche un peu et bois un verre d'eau. Cela réinitialise ta concentration.
          </p>
        </div>
        <div className="bg-amber-50 p-6 rounded-2xl border border-amber-100">
          <h4 className="font-bold text-amber-800 mb-2">🧘 La Pleine Conscience</h4>
          <p className="text-sm text-amber-700 leading-relaxed">
            Ferme les yeux et identifie 3 bruits autour de toi, 3 sensations physiques (tes pieds au sol, l'air sur ton visage) et 1 odeur.
          </p>
        </div>
      </section>
    </div>
  );
};

export default RelaxView;

