  { id: 2, question: "Plus j'en ai, moins on y voit. Qui suis-je ?", answer: "l'obscurité", hint: "Opposé de la lumière." },
  { id: 3, question: "Qu'est-ce qui est aussi grand qu'un éléphant mais ne pèse rien ?", answer: "son ombre", hint: "Elle te suit quand il y a du soleil." },
  { id: 4, question: "J'ai des villes, mais pas de maisons. J'ai des montagnes, mais pas d'arbres. J'ai de l'eau, mais pas de poissons. Qui suis-je ?", answer: "une carte", hint: "Tu l'utilises pour te repérer." },
];

const GamesView: React.FC = () => {
  const [currentRiddle, setCurrentRiddle] = useState(0);
  const [userAnswer, setUserAnswer] = useState('');
  const [showHint, setShowHint] = useState(false);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error' | null, msg: string }>({ type: null, msg: '' });

  const checkAnswer = () => {
    const normalize = (s: string) => s.toLowerCase().trim().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g,"");
    if (normalize(userAnswer).includes(normalize(riddles[currentRiddle].answer))) {
      setFeedback({ type: 'success', msg: 'Bravo ! C\'est la bonne réponse.' });
    } else {
      setFeedback({ type: 'error', msg: 'Pas tout à fait... réessaye !' });
    }
  };

  const nextRiddle = () => {
    setCurrentRiddle((prev) => (prev + 1) % riddles.length);
    setUserAnswer('');
    setShowHint(false);
    setFeedback({ type: null, msg: '' });
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <h2 className="text-3xl font-bold text-gray-800">Détente Intelligente</h2>

      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 max-w-2xl mx-auto">
        <div className="flex justify-between items-center mb-6">
          <span className="text-xs font-bold uppercase tracking-widest text-amber-500">Casse-tête #{riddles[currentRiddle].id}</span>
          <span className="text-xs text-gray-400">{currentRiddle + 1} / {riddles.length}</span>
        </div>

        <p className="text-xl font-medium text-gray-800 mb-8 leading-relaxed">
          « {riddles[currentRiddle].question} »
        </p>

        <div className="space-y-4">
          <input 
            type="text" 
            value={userAnswer}
            onChange={(e) => setUserAnswer(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && checkAnswer()}
            placeholder="Ta réponse..."
            className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-amber-400 outline-none transition-colors"
          />

          <div className="flex space-x-3">
            <button 
              onClick={checkAnswer}
              className="flex-grow bg-amber-500 hover:bg-amber-600 text-white font-bold py-3 rounded-xl transition-colors"
            >
              Vérifier
            </button>
            <button 
              onClick={() => setShowHint(true)}
              className="px-4 py-3 bg-amber-50 text-amber-600 font-medium rounded-xl hover:bg-amber-100 transition-colors"
            >
              Indice 💡
            </button>
          </div>

          {showHint && (
            <p className="text-sm text-amber-700 bg-amber-50 p-3 rounded-lg border border-amber-100 italic">
              Indice : {riddles[currentRiddle].hint}
            </p>
          )}

          {feedback.type && (
            <div className={`p-4 rounded-xl text-center font-medium ${
              feedback.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'
            }`}>
              {feedback.msg}
              {feedback.type === 'success' && (
                <button 
                  onClick={nextRiddle}
                  className="block mx-auto mt-2 text-sm underline font-bold"
                >
                  Suivant →
                </button>
              )}
            </div>
          )}
        </div>
      </section>

      <div className="text-center p-6 border-2 border-dashed border-gray-200 rounded-2xl">
        <p className="text-gray-500">D'autres jeux logiques (casse-têtes visuels, suites numériques) arrivent bientôt !</p>
      </div>
    </div>
  );
};

