      setRiddleFeedback({ type: 'success', msg: 'Bravo ! C\'est la bonne réponse.' });
    } else {
      setRiddleFeedback({ type: 'error', msg: 'Pas tout à fait... réessaye !' });
    }
  };

  const nextRiddle = () => {
    setCurrentRiddle((prev) => (prev + 1) % riddles.length);
    setUserAnswer('');
    setShowHint(false);
    setRiddleFeedback({ type: null, msg: '' });
  };

  const handleMemoryClick = (index: number) => {
    if (selected.length === 2 || selected.includes(index) || solved.includes(index)) return;
    const newSelected = [...selected, index];
    setSelected(newSelected);
    if (newSelected.length === 2) {
      if (memoryGrid[newSelected[0]] === memoryGrid[newSelected[1]]) {
        setSolved([...solved, ...newSelected]);
        setSelected([]);
      } else {
        setTimeout(() => setSelected([]), 1000);
      }
    }
  };

  const handleMathCheck = () => {
    if (parseInt(mathInput) === mathProblem.result) {
      setMathScore(mathScore + 1);
      generateMath();
    } else {
      setMathInput('');
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-3xl font-bold text-gray-800">Détente Intelligente</h2>
        <div className="flex bg-gray-100 p-1 rounded-xl">
          <button 
            onClick={() => setActiveGame('riddles')}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeGame === 'riddles' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}
          >
            Énigmes
          </button>
          <button 
            onClick={() => setActiveGame('memory')}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeGame === 'memory' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}
          >
            Mémoire
          </button>
          <button 
            onClick={() => setActiveGame('math')}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeGame === 'math' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}
          >
            Calcul
          </button>
        </div>
      </div>

      {activeGame === 'riddles' && (
        <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 max-w-2xl mx-auto">
          <div className="flex justify-between items-center mb-6">
            <span className="text-xs font-bold uppercase tracking-widest text-amber-500">Casse-tête #{riddles[currentRiddle].id}</span>
            <span className="text-xs text-gray-400">{currentRiddle + 1} / {riddles.length}</span>
          </div>
          <p className="text-xl font-medium text-gray-800 mb-8">« {riddles[currentRiddle].question} »</p>
          <div className="space-y-4">
            <input 
              type="text" 
              value={userAnswer}
              onChange={(e) => setUserAnswer(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleRiddleCheck()}
              placeholder="Ta réponse..."
              className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-amber-400 outline-none"
            />
            <div className="flex space-x-3">
              <button onClick={handleRiddleCheck} className="flex-grow bg-amber-500 hover:bg-amber-600 text-white font-bold py-3 rounded-xl">Vérifier</button>
              <button onClick={() => setShowHint(true)} className="px-4 py-3 bg-amber-50 text-amber-600 font-medium rounded-xl">Indice 💡</button>
            </div>
            {showHint && <p className="text-sm text-amber-700 bg-amber-50 p-3 rounded-lg border border-amber-100">Indice : {riddles[currentRiddle].hint}</p>}
            {riddleFeedback.type && (
              <div className={`p-4 rounded-xl text-center font-medium ${riddleFeedback.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'}`}>
                {riddleFeedback.msg}
                {riddleFeedback.type === 'success' && <button onClick={nextRiddle} className="block mx-auto mt-2 text-sm underline font-bold">Suivant →</button>}
              </div>
            )}
          </div>
        </section>
      )}

      {activeGame === 'memory' && (
        <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 max-w-md mx-auto">
          <h3 className="text-center font-bold text-gray-700 mb-6">Mémorise les paires d'animaux</h3>
          <div className="grid grid-cols-4 gap-3">
            {memoryGrid.map((val, idx) => (
              <div 
                key={idx}
                onClick={() => handleMemoryClick(idx)}
                className={`aspect-square rounded-xl flex items-center justify-center text-3xl cursor-pointer transition-all duration-300 ${
                  selected.includes(idx) || solved.includes(idx) ? 'bg-indigo-50 rotate-y-180' : 'bg-indigo-600'
                }`}
              >
                {(selected.includes(idx) || solved.includes(idx)) ? symbols[val] : ''}
              </div>
            ))}
          </div>
          {solved.length === memoryGrid.length && (
            <div className="mt-6 text-center text-emerald-600 font-bold animate-bounce">
              Bravo ! Tu as tout trouvé ! 🎉
            </div>
          )}
        </section>
      )}

      {activeGame === 'math' && (
        <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 max-w-sm mx-auto text-center">
          <div className="mb-4 text-sm text-gray-500">Score: <span className="font-bold text-indigo-600">{mathScore}</span></div>
          <h3 className="text-4xl font-mono font-bold mb-8 text-gray-800">
            {mathProblem.a} {mathProblem.op} {mathProblem.b} = ?
          </h3>
          <input 
            type="number" 
            value={mathInput}
            autoFocus
            onChange={(e) => setMathInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleMathCheck()}
            className="w-full text-center p-4 text-2xl border-2 border-gray-100 rounded-xl focus:border-indigo-400 outline-none mb-4"
          />
          <button 
            onClick={handleMathCheck}
            className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl hover:bg-indigo-700"
          >
            Valider
          </button>
        </section>
      )}
    </div>
  );
};

export default GamesView;

